import { X } from '@hexa-ui/icons';
import React, { Ref } from 'react';
import { useChipContext } from '../../ChipContext';
import { ChipDeleteIconButton } from './ChipDeleteIcon.styles';
import { ChipDeleteIconProps } from './ChipDeleteIcon.types';

export const ChipDeleteIcon = React.forwardRef(
  (
    { onDelete, ...restProps }: ChipDeleteIconProps,
    forwardedRef: Ref<HTMLButtonElement>
  ): JSX.Element => {
    const chipContext = useChipContext();

    if (!chipContext) {
      // eslint-disable-next-line no-console
      console.warn(
        'Missing chip context, make sure that Chip.DeleteIcon is being used as a child of Chip.Root'
      );
      return <></>;
    }

    const { disabled } = chipContext;

    return (
      <ChipDeleteIconButton
        {...restProps}
        ref={forwardedRef}
        data-testid="chip-delete-icon"
        icon={() => <X />}
        onClick={(event: React.MouseEvent<HTMLButtonElement>) => {
          event.stopPropagation();
          onDelete();
        }}
        onKeyDown={(event: React.KeyboardEvent<HTMLButtonElement>) => event.stopPropagation()}
        variant="inherit"
        size="tiny"
        disabled={disabled}
        aria-disabled={disabled}
        aria-hidden="true"
        aria-label={restProps['aria-label'] || 'Delete icon chip button'}
      />
    );
  }
);
